/// Pure logical check: is `n` even?
fn is_even(n: u32) -> bool {
    n % 2 == 0
}

/// Runtime version (just delegates to `is_even`).
fn is_even_exec(n: u32) -> bool {
    is_even(n)
}

/// Returns true if and only if there exists at least one even element in `arr`.
fn is_product_even(arr: &Vec<u32>) -> bool {
    arr.iter().any(|&x| is_even_exec(x))
}

